# Generated by KernelGen: https://github.com/flagos-ai/KernelGen

"""gcu400 matmuladd: the common matmul + bias kernel with broadcast-safe bias loads.

The common ``flag_gems.fused.matmuladd`` loads the bias through a 2-D tile whose
pointer is ``bias.broadcast_to(out.shape)``.  When the bias is 1-D (shape ``(N,)``)
that view has stride 0 along M, and a masked 2-D ``tl.load`` from a stride-0
source with more than one valid row aborts the device on gcu400 (the DMA
slice_pad path faults; the process dies at the first ``synchronize`` with
SIGABRT/SIGKILL).  This copy therefore loads broadcast biases as a 1-D row /
column / scalar and broadcasts them in registers, keeping the plain 2-D load
only for a fully materialized 2-D bias (non-zero strides on both dims, which is
safe on this backend).
"""

import logging
import os

import torch
import triton
import triton.language as tl

from flag_gems import runtime
from flag_gems.runtime import torch_device_fn
from flag_gems.utils import broadcastable_to, libentry, libtuner
from flag_gems.utils import triton_lang_extension as tle

logger = logging.getLogger(__name__)

BIAS_MODE_FULL = tl.constexpr(0)
BIAS_MODE_ROW = tl.constexpr(1)
BIAS_MODE_COL = tl.constexpr(2)
BIAS_MODE_SCALAR = tl.constexpr(3)


@libentry()
@libtuner(
    configs=(
        runtime.ops_get_configs("addmm", pre_hook=None)
        if os.environ.get("USE_FLAGTUNE") == "1"
        else runtime.get_tuned_config("addmm")
    ),
    key=["M", "N", "K"],
    strategy=(
        runtime.get_expand_config("addmm")["strategy"]
        if os.environ.get("USE_FLAGTUNE") == "1"
        else ["align32", "align32", "align32"]
    ),
    warmup=5,
    rep=10,
)
@triton.jit
def matmuladd_kernel(
    a_ptr,
    b_ptr,
    c_ptr,
    bias_ptr,
    M,
    N,
    K,
    stride_am,
    stride_ak,
    stride_bk,
    stride_bn,
    stride_cm,
    stride_cn,
    stride_bias_m,
    stride_bias_n,
    BLOCK_SIZE_M: tl.constexpr,
    BLOCK_SIZE_N: tl.constexpr,
    BLOCK_SIZE_K: tl.constexpr,
    BIAS_MODE: tl.constexpr,
):
    pid_m = tle.program_id(0)
    pid_n = tle.program_id(1)

    offs_am = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)
    offs_bn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)
    offs_k = tl.arange(0, BLOCK_SIZE_K)
    a_ptrs = a_ptr + (offs_am[:, None] * stride_am + offs_k[None, :] * stride_ak)
    b_ptrs = b_ptr + (offs_k[:, None] * stride_bk + offs_bn[None, :] * stride_bn)

    accumulator = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)
    for k in range(0, tl.cdiv(K, BLOCK_SIZE_K)):
        a = tl.load(
            a_ptrs,
            mask=(offs_am[:, None] < M) & (offs_k[None, :] < K - k * BLOCK_SIZE_K),
            other=0.0,
        )
        b = tl.load(
            b_ptrs,
            mask=(offs_k[:, None] < K - k * BLOCK_SIZE_K) & (offs_bn[None, :] < N),
            other=0.0,
        )
        accumulator += tl.dot(a, b, allow_tf32=False)
        a_ptrs += BLOCK_SIZE_K * stride_ak
        b_ptrs += BLOCK_SIZE_K * stride_bk

    offs_cm = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)
    offs_cn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)
    out_mask = (offs_cm[:, None] < M) & (offs_cn[None, :] < N)

    # A masked 2-D load from a stride-0 (broadcast) source faults the device on
    # gcu400 when it covers more than one valid row/column, so broadcast biases
    # are gathered as 1-D / scalar loads and expanded in registers instead.
    if BIAS_MODE == BIAS_MODE_ROW:
        bias_row = tl.load(
            bias_ptr + offs_cn * stride_bias_n, mask=offs_cn < N, other=0.0
        )
        accumulator = accumulator + bias_row[None, :]
    elif BIAS_MODE == BIAS_MODE_COL:
        bias_col = tl.load(
            bias_ptr + offs_cm * stride_bias_m, mask=offs_cm < M, other=0.0
        )
        accumulator = accumulator + bias_col[:, None]
    elif BIAS_MODE == BIAS_MODE_SCALAR:
        bias_scalar = tl.load(bias_ptr)
        accumulator = accumulator + bias_scalar
    else:
        bias_ptrs = (
            bias_ptr
            + stride_bias_m * offs_cm[:, None]
            + stride_bias_n * offs_cn[None, :]
        )
        bias = tl.load(bias_ptrs, mask=out_mask, other=0.0)
        accumulator = accumulator + bias

    c = accumulator.to(bias_ptr.dtype.element_ty)

    c_ptrs = c_ptr + stride_cm * offs_cm[:, None] + stride_cn * offs_cn[None, :]
    tl.store(c_ptrs, c, mask=out_mask)


def _select_bias_mode(bias):
    """Pick the in-kernel bias load shape for a 2-D (possibly broadcast) bias.

    A 2-D masked ``tl.load`` from a stride-0 source faults the device on
    gcu400 once it spans more than one valid row/column, so any broadcast
    bias is served by a 1-D / scalar load instead (see module docstring).
    """
    stride_m, stride_n = bias.stride(0), bias.stride(1)
    if stride_m == 0 and stride_n == 0:
        return BIAS_MODE_SCALAR
    if stride_m == 0:
        return BIAS_MODE_ROW
    if stride_n == 0:
        return BIAS_MODE_COL
    return BIAS_MODE_FULL


def _matmuladd(input, other, bias, out=None):
    assert input.shape[1] == other.shape[0], "Incompatible dimensions"
    assert broadcastable_to(
        bias.shape, (input.shape[0], other.shape[1])
    ), "Incompatible input shape"
    M, K = input.shape
    _, N = other.shape
    if out is None:
        out = torch.empty((M, N), device=input.device, dtype=input.dtype)
    else:
        assert out.shape == (M, N), "Incompatible output shape"
    input = input.contiguous()
    bias = bias.broadcast_to(out.shape)
    bias_mode = _select_bias_mode(bias)

    grid = lambda META: (
        triton.cdiv(M, META["BLOCK_SIZE_M"]),
        triton.cdiv(N, META["BLOCK_SIZE_N"]),
    )
    with torch_device_fn.device(input.device):
        matmuladd_kernel[grid](
            input,
            other,
            out,
            bias,
            M,
            N,
            K,
            input.stride(0),
            input.stride(1),
            other.stride(0),
            other.stride(1),
            out.stride(0),
            out.stride(1),
            bias.stride(0),
            bias.stride(1),
            BIAS_MODE=bias_mode,
        )
    return out


def matmuladd(input, other, bias):
    """
    Matrix multiplication with addition: output = matmul(input, other) + bias
    """
    logger.debug("GEMS MATMULADD")
    return _matmuladd(input, other, bias)
